ALL_EDITS = [('src/memory/store.py', '    def save(self) -> None:\n', '    def _personal(self) -> dict:\n        """Lo que se guarda en la memoria PERSONAL: sin lo que viene de cartuchos montados (parche-91), que se recompone al arrancar."""\n        from src.memory.cartuchos import duenos\n        own_pairs = [p for d in getattr(self, "cart_own", {}).values() for p in d.get("opposites", [])]\n        data = {"concepts": self.concepts, "facts": [f for f in self.facts if not f.get("cart")], "past": self.past, "alias": self.alias,\n                "opposites": [p for p in self.opposites if list(p) not in own_pairs], "verb_isa": self.verb_isa, "defs": self.defs, "lessons": self.lessons,\n                "tick": self.tick, "surface": self.surface, "display": self.display}\n        for sec in ("alias", "verb_isa", "defs", "surface", "display"):\n            own = duenos(self, sec)\n            if own:\n                data[sec] = {k: v for k, v in data[sec].items() if k not in own}\n        return data\n\n    def save(self) -> None:\n', 'def _personal(self)'), ('src/memory/store.py', 'json.dump({"concepts": self.concepts, "facts": self.facts, "past": self.past, "alias": self.alias, "opposites": self.opposites, "verb_isa": self.verb_isa, "defs": self.defs, "lessons": self.lessons, "tick": self.tick,\n                       "surface": self.surface, "display": self.display},\n                      handle,', 'json.dump(self._personal(),\n                      handle,', 'json.dump(self._personal()'), ('scripts/think.py', '            added = load_seed(memory, school)\n', '            added = load_seed(memory, school)\n            try:                                                  # parche-91: cartuchos de conocimiento activos (cartuchos/activos.json)\n                from src.memory.cartuchos import montar\n                for _n, _k in montar(memory):\n                    print(f" [cartucho] {_n}: " + (f"{_k} hechos" if _k is not None else f"NO ENCONTRADO (quitalo: python -m scripts.cartucho retirar {_n})"))\n            except Exception as _e:                               # noqa\n                print(f" [cartucho] no se pudieron montar: {_e!r}")\n', 'from src.memory.cartuchos import montar')]
NEW_FILES = {'src/language/ingesta.py': '"""Ingesta de TEXTOS (parche-91): lee un texto en lenguaje natural (p. ej. sobre el sistema solar), lo prepara frase a frase y lo pasa por la conversacion\nreal (la misma que usas en scripts.think: escuela, discurso con tema, correcciones, memoria). Despues se AUTOEXAMINA: por cada sujeto aprendido pregunta\n"¿Qué sabes de X?" y comprueba que sus datos salen en la respuesta. Devuelve un informe de lo aprendido / no entendido / recordado.\nNo hay LLM: si una frase no se entiende, se dice cual es y por que familia fallan (para arreglarlas por familias en el siguiente parche)."""\nimport re\nfrom typing import Dict, List, Tuple\n\nfrom .lexicon import norm\n\nCONECTORES = r"(?:adem[aá]s|asimismo|por otro lado|sin embargo|por eso|por ello|as[ií]|por lo tanto|en resumen|en consecuencia|adem[aá]s de eso|de hecho|entonces|igualmente|tambi[eé]n)"\n\n\ndef limpiar(frase: str) -> str:\n    f = re.sub(r"\\([^)]*\\)", " ", frase)                                  # (aclaraciones entre parentesis)\n    f = re.sub(r"\\[[^\\]]*\\]|\\bpag\\.\\s*\\d+", " ", f)\n    f = re.sub(r"\\s*[—–]\\s*[^—–]*?\\s*[—–]\\s*", ", ", f)                  # incisos entre rayas\n    f = re.sub(r"^\\s*" + CONECTORES + r"\\s*,?\\s+", "", f, flags=re.I)      # "Además, ..." -> "..."\n    f = re.sub(r"\\s+([.,;:!?])", r"\\1", re.sub(r"\\s+", " ", f)).strip(" ,;")\n    if f and f[0].islower():\n        f = f[0].upper() + f[1:]\n    return f\n\n\ndef preparar(texto: str) -> Tuple[List[str], List[str]]:\n    """-> (frases, titulos_ignorados). Una linea corta sin punto final es un titulo; \'#\' son comentarios."""\n    frases, titulos = [], []\n    for linea in texto.splitlines():\n        linea = linea.strip()\n        if not linea or linea.startswith("#"):\n            continue\n        if not re.search(r"[.!?:]$", linea) and len(linea.split()) <= 6:\n            titulos.append(linea)\n            continue\n        for trozo in re.split(r"(?<=[.!?])\\s+", linea):\n            for parte in re.split(r";\\s+", trozo):                         # "A es B; C es D." -> dos frases\n                f = limpiar(parte)\n                if len(f.split()) >= 2:\n                    frases.append(f if re.search(r"[.!?]$", f) else f + ".")\n    return frases, titulos\n\n\ndef clasificar(respuesta: str) -> str:\n    r = norm(respuesta or "")\n    if "no he entendido" in r or "puedes decirlo" in r or "frase mas simple" in r:\n        return "no_entendida"\n    if "entendido:" in r:\n        return "aprendida"\n    return "otra"\n\n\ndef leer(conv, mem, frases: List[str]) -> Dict:\n    """Pasa las frases por la conversacion. Devuelve {aprendidas, no_entendidas, otras, hechos_nuevos}."""\n    rep = {"aprendidas": [], "no_entendidas": [], "otras": [], "hechos_nuevos": []}\n    for f in frases:\n        antes = len(mem.facts)\n        resp = conv.say(f)\n        if getattr(conv.d, "pending", None):                              # en lectura por lotes no se puede contestar a preguntas de aclaracion\n            conv.d.pending = None\n            rep["otras"].append((f, "pregunta de aclaracion (conflicto con lo que ya sabia): " + resp[:120]))\n        c = clasificar(resp)\n        nuevos = [x for x in mem.facts[antes:] if not x.get("neg")]\n        rep["hechos_nuevos"] += nuevos\n        if c == "aprendida":\n            rep["aprendidas"].append((f, resp))\n        elif c == "no_entendida":\n            rep["no_entendidas"].append((f, resp))\n        else:\n            rep["otras"].append((f, resp))\n    return rep\n\n\ndef comprobar(conv, mem, hechos: List[dict]) -> Tuple[int, int, List[Tuple[str, str, str]]]:\n    """Autoexamen de retencion: por sujeto, \'¿Qué sabes de X?\' debe nombrar cada objeto aprendido. -> (ok, total, fallos[(sujeto, objeto, respuesta)])"""\n    por: Dict[str, List[str]] = {}\n    for h in hechos:\n        por.setdefault(h["s"], [])\n        if h["o"] not in por[h["s"]]:\n            por[h["s"]].append(h["o"])\n    ok = total = 0\n    fallos = []\n    for s, objs in por.items():\n        disp = mem.display.get(s, s.lower())\n        resp = norm(conv.say(f"¿Qué sabes de {disp}?"))\n        for o in objs:\n            total += 1\n            od = norm(mem.display.get(o, o.lower()))\n            if od and od in resp:\n                ok += 1\n            else:\n                fallos.append((disp, od, resp[:100]))\n    return ok, total, fallos\n\n\ndef informe(rep: Dict, titulos: List[str], chk: Tuple[int, int, list]) -> str:\n    a, n_, o = len(rep["aprendidas"]), len(rep["no_entendidas"]), len(rep["otras"])\n    tot = a + n_ + o\n    L = [f"LECTURA: {tot} frases -> {a} aprendidas, {n_} no entendidas, {o} otras  ({a / max(tot, 1):.0%} entendido). Hechos nuevos: {len(rep[\'hechos_nuevos\'])}."]\n    if titulos:\n        L.append("Títulos ignorados: " + " | ".join(titulos))\n    ok, total, fallos = chk\n    L.append(f"RETENCIÓN (¿Qué sabes de X?): {ok}/{total} = {ok / max(total, 1):.0%}")\n    if rep["no_entendidas"]:\n        L.append("\\nFRASES NO ENTENDIDAS:")\n        L += [f"  - {f}" for f, _ in rep["no_entendidas"]]\n    if rep["otras"]:\n        L.append("\\nOTRAS RESPUESTAS:")\n        L += [f"  - {f}  ->  {r[:110]}" for f, r in rep["otras"]]\n    if fallos:\n        L.append("\\nDATOS APRENDIDOS QUE NO SALEN AL PREGUNTAR:")\n        L += [f"  - {s}: falta «{o}»  (respuesta: {r!r})" for s, o, r in fallos]\n    L.append("\\nLO APRENDIDO:")\n    seen = set()\n    for h in rep["hechos_nuevos"]:\n        k = (h["s"], h["p"], h["o"])\n        if k not in seen:\n            seen.add(k)\n            L.append(f"  {h[\'s\']} {h[\'p\']} {h[\'o\']}")\n    return "\\n".join(L)\n', 'src/memory/cartuchos.py': '"""CARTUCHOS de conocimiento (parche-91). Cada texto aprendido es un fichero propio en cartuchos/<nombre>.json (hechos + como se dijeron). La memoria que usa el\nmodelo se COMPONE al arrancar:  fabrica (semilla) + cartuchos activos (cartuchos/activos.json) + tu memoria personal. La memoria personal (memory/lcm_memory.json)\nNUNCA contiene lo de los cartuchos (MemoryStore.save lo filtra), asi que retirar un cartucho no deja restos: se quita de la lista y listo.\nLo deducido se calcula al preguntar, de modo que tampoco queda nada deducido de un cartucho retirado."""\nimport copy\nimport json\nimport os\nimport time\nfrom typing import Dict, List, Optional\n\nDIR = "cartuchos"\nSECCIONES = ("alias", "verb_isa", "defs", "surface", "display")\n\n\ndef _p(base: str, *a) -> str:\n    return os.path.join(base, *a)\n\n\ndef activos(base: str = DIR) -> List[str]:\n    try:\n        return list(json.load(open(_p(base, "activos.json"), encoding="utf-8")))\n    except (OSError, ValueError):\n        return []\n\n\ndef _guardar_activos(lista: List[str], base: str) -> None:\n    os.makedirs(base, exist_ok=True)\n    json.dump(lista, open(_p(base, "activos.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)\n\n\ndef insertar(nombre: str, base: str = DIR) -> bool:\n    if not os.path.exists(_p(base, nombre + ".json")):\n        return False\n    a = activos(base)\n    if nombre not in a:\n        _guardar_activos(a + [nombre], base)\n    return True\n\n\ndef retirar(nombre: str, base: str = DIR) -> bool:\n    a = activos(base)\n    if nombre not in a:\n        return False\n    _guardar_activos([x for x in a if x != nombre], base)\n    return True\n\n\ndef cargar(nombre: str, base: str = DIR) -> Optional[dict]:\n    try:\n        return json.load(open(_p(base, nombre + ".json"), encoding="utf-8"))\n    except (OSError, ValueError):\n        return None\n\n\ndef listar(base: str = DIR):\n    """[(nombre, activo, n_hechos, fuente)]"""\n    act = set(activos(base))\n    out = []\n    if os.path.isdir(base):\n        for f in sorted(os.listdir(base)):\n            if f.endswith(".json") and f != "activos.json":\n                c = cargar(f[:-5], base) or {}\n                out.append((f[:-5], f[:-5] in act, len(c.get("hechos", [])), c.get("fuente", "")))\n    return out\n\n\ndef borrar(nombre: str, base: str = DIR) -> bool:\n    retirar(nombre, base)\n    p = _p(base, nombre + ".json")\n    if os.path.exists(p):\n        os.remove(p)\n        return True\n    return False\n\n\n# ---- compuesto en memoria -------------------------------------------------------------------\ndef _own(mem) -> Dict[str, dict]:\n    if not hasattr(mem, "cart_own"):\n        mem.cart_own = {}\n    return mem.cart_own\n\n\ndef duenos(mem, seccion: str) -> set:\n    """Claves de una seccion que pertenecen a algun cartucho montado (para no guardarlas en la memoria personal)."""\n    out = set()\n    for d in getattr(mem, "cart_own", {}).values():\n        out |= set(d.get(seccion, []))\n    return out\n\n\ndef _key(f: dict):\n    return (f["s"], f["p"], f["o"], bool(f.get("neg")))\n\n\ndef _montar_uno(mem, nombre: str, c: dict) -> int:\n    own = _own(mem)[nombre] = {s: [] for s in SECCIONES}\n    own["opposites"] = []\n    have = {_key(f) for f in mem.facts}\n    n = 0\n    for f in c.get("hechos", []):\n        if _key(f) not in have:\n            g = copy.deepcopy(f)\n            g["cart"] = nombre\n            mem.facts.append(g)\n            n += 1\n    for s in SECCIONES:\n        d = getattr(mem, s)\n        for k, v in c.get(s, {}).items():\n            if k not in d:\n                d[k] = v\n                own[s].append(k)\n    for pair in c.get("opposites", []):\n        if list(pair) not in mem.opposites:\n            mem.opposites.append(list(pair))\n            own["opposites"].append(list(pair))\n    return n\n\n\ndef desmontar(mem, nombre: str) -> int:\n    own = getattr(mem, "cart_own", {}).pop(nombre, None)\n    before = len(mem.facts)\n    mem.facts = [f for f in mem.facts if f.get("cart") != nombre]\n    if own:\n        for s in SECCIONES:\n            d = getattr(mem, s)\n            for k in own.get(s, []):\n                d.pop(k, None)\n        mem.opposites = [p for p in mem.opposites if list(p) not in own.get("opposites", [])]\n    return before - len(mem.facts)\n\n\ndef montar(mem, base: str = DIR, excluir: Optional[str] = None):\n    """Quita lo montado antes y monta los cartuchos activos (menos `excluir`). -> [(nombre, hechos_anadidos | None si falta el fichero)]"""\n    for nombre in list(getattr(mem, "cart_own", {})):\n        desmontar(mem, nombre)\n    res = []\n    for nombre in activos(base):\n        if nombre == excluir:\n            continue\n        c = cargar(nombre, base)\n        res.append((nombre, _montar_uno(mem, nombre, c) if c else None))\n    return res\n\n\n# ---- crear un cartucho ----------------------------------------------------------------------\ndef instantanea(mem) -> dict:\n    return {"facts": {_key(f) for f in mem.facts}, **{s: set(getattr(mem, s)) for s in SECCIONES}, "opposites": [list(p) for p in mem.opposites]}\n\n\ndef delta(mem, snap: dict) -> dict:\n    d = {"hechos": [copy.deepcopy({k: v for k, v in f.items() if k != "cart"}) for f in mem.facts if _key(f) not in snap["facts"] and not f.get("cart")]}\n    for s in SECCIONES:\n        d[s] = {k: v for k, v in getattr(mem, s).items() if k not in snap[s]}\n    d["opposites"] = [p for p in mem.opposites if list(p) not in snap["opposites"]]\n    return d\n\n\ndef guardar_cartucho(nombre: str, contenido: dict, meta: Optional[dict] = None, base: str = DIR) -> str:\n    os.makedirs(base, exist_ok=True)\n    c = dict(contenido)\n    c.update({"nombre": nombre, "creado": time.strftime("%Y-%m-%d %H:%M"), "version": 1})\n    c.update(meta or {})\n    p = _p(base, nombre + ".json")\n    json.dump(c, open(p, "w", encoding="utf-8"), ensure_ascii=False, indent=1)\n    return p\n', 'scripts/leer_texto.py': '"""Lee un texto en lenguaje natural y lo convierte en un CARTUCHO de conocimiento (parche-91).\n\n  python -m scripts.leer_texto data/textos/sistema_solar.txt            crea cartuchos/sistema_solar.json y lo INSERTA (activo)\n  python -m scripts.leer_texto mi_texto.txt --nombre astronomia         con otro nombre\n  python -m scripts.leer_texto mi_texto.txt --prueba                    lee y mide, sin crear cartucho\n\nEl texto se lee sobre una memoria de usar y tirar (fabrica + cartuchos activos), asi que el cartucho contiene SOLO lo que aporta el texto y no tu memoria\npersonal. Retirarlo: python -m scripts.cartucho retirar NOMBRE.  Escribe reports/lectura.txt (aprendido / no entendido / autoexamen de retencion)."""\nimport argparse\nimport os\nimport sys\nimport tempfile\nfrom datetime import date\n\nimport torch\n\nfrom src.language.dialogue import Conversation\nfrom src.language.ingesta import comprobar, informe, leer, preparar\nfrom src.language.qa import QA\nfrom src.language.school_parser import SchoolParser\nfrom src.language.ud import load_school\nfrom src.memory import cartuchos\nfrom src.memory.store import MemoryStore\nfrom src.reasoning.lessons import deduce_all\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("archivo")\n    ap.add_argument("--nombre", default=None)\n    ap.add_argument("--prueba", action="store_true", help="no crear cartucho")\n    a = ap.parse_args()\n    if not os.path.exists(a.archivo):\n        sys.exit(f"No encuentro {a.archivo}")\n    nombre = a.nombre or os.path.splitext(os.path.basename(a.archivo))[0].lower().replace(" ", "_")\n    device = "cuda" if torch.cuda.is_available() else ("mps" if torch.backends.mps.is_available() else "cpu")\n    try:\n        from src.language.school_learn import load_overrides\n        ov = load_overrides()\n    except Exception:                                                     # noqa\n        ov = None\n    model, scripts = load_school(device=device)\n    parser = SchoolParser(model, device, scripts, ov) if ov is not None else SchoolParser(model, device, scripts)\n    with tempfile.TemporaryDirectory() as d:\n        mem = MemoryStore(os.path.join(d, "lectura.json"))\n        mem.today = parser.today = date.today()\n        from src.language.semilla import load_seed\n        load_seed(mem, parser)\n        cartuchos.montar(mem, excluir=nombre)                             # contexto: fabrica + cartuchos activos (para entender referencias)\n        snap = cartuchos.instantanea(mem)\n        conv = Conversation(mem, parser, lambda m, p: QA(m, p.parse, lambda facts: deduce_all(facts, m.active_lessons())))\n        frases, titulos = preparar(open(a.archivo, encoding="utf-8").read())\n        rep = leer(conv, mem, frases)\n        chk = comprobar(conv, mem, rep["hechos_nuevos"])\n        contenido = cartuchos.delta(mem, snap)\n    text = informe(rep, titulos, chk)\n    os.makedirs("reports", exist_ok=True)\n    open("reports/lectura.txt", "w", encoding="utf-8").write(text)\n    print(text)\n    if a.prueba:\n        print("\\n[--prueba: no se ha creado ningun cartucho]")\n        return\n    ruta = cartuchos.guardar_cartucho(nombre, contenido, {"fuente": a.archivo, "frases": len(frases), "no_entendidas": [f for f, _ in rep["no_entendidas"]]})\n    cartuchos.insertar(nombre)\n    print(f"\\n[Cartucho «{nombre}» creado ({len(contenido[\'hechos\'])} hechos) en {ruta} e INSERTADO. Pregunta en python -m scripts.think. Retirarlo: python -m scripts.cartucho retirar {nombre}]")\n\n\nif __name__ == "__main__":\n    main()\n', 'scripts/cartucho.py': '"""Gestion de cartuchos de conocimiento (parche-91).\n  python -m scripts.cartucho listar\n  python -m scripts.cartucho insertar NOMBRE      (activa un cartucho que ya existe)\n  python -m scripts.cartucho retirar NOMBRE       (lo desactiva: olvida SOLO lo suyo; los demas cartuchos y la fabrica siguen)\n  python -m scripts.cartucho borrar NOMBRE        (lo retira Y borra su fichero)\nLos cambios se notan al arrancar scripts.think (la memoria se recompone al arrancar)."""\nimport sys\n\nfrom src.memory import cartuchos\n\n\ndef main(argv=None):\n    argv = list(sys.argv[1:] if argv is None else argv)\n    if not argv or argv[0] not in ("listar", "insertar", "retirar", "borrar") or (argv[0] != "listar" and len(argv) < 2):\n        print(__doc__)\n        return 1\n    cmd = argv[0]\n    if cmd == "listar":\n        filas = cartuchos.listar()\n        if not filas:\n            print("No hay cartuchos. Crea uno con: python -m scripts.leer_texto TEXTO.txt")\n        for nombre, act, n, fuente in filas:\n            print(f"  [{\'INSERTADO\' if act else \'retirado \'}] {nombre:24s} {n:4d} hechos   (de {fuente})")\n        print("  [fabrica] semilla (siempre presente)")\n        return 0\n    nombre = argv[1]\n    ok = {"insertar": cartuchos.insertar, "retirar": cartuchos.retirar, "borrar": cartuchos.borrar}[cmd](nombre)\n    print(("Hecho: " if ok else "Nada que hacer: ") + f"{cmd} {nombre}")\n    return 0 if ok else 1\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'scripts/poda.py': '"""Poda segura (parche-91):  python -m scripts.poda            (SIMULA: solo lista lo que sobra y cuanto pesa)\n                              python -m scripts.poda --aplicar  (MUEVE lo listado a _poda/<fecha>/ conservando rutas; no borra nada)\nCandidatos: caches (__pycache__, .pytest_cache, *.pyc, .DS_Store), copias de parches (.parche_backups), parche-NN.py ya aplicados en la raiz (git guarda su\nhistoria), paquetes zip de la raiz y de reports/, ficheros .tmp y data/autoexamen.tsv (se regenera). NUNCA toca .git, .venv, checkpoints, memory, cartuchos, data ni src.\nHaz commit antes de aplicar. Para deshacer: mueve de vuelta lo que hay en _poda/."""\nimport os\nimport re\nimport shutil\nimport sys\nimport time\n\nPROTEGIDO = {".git", ".venv", "venv", "checkpoints", "memory", "cartuchos", "src", "tests", "configs", "_poda", "node_modules"}\nROOT = "."\n\n\ndef _size(p):\n    if os.path.isfile(p):\n        return os.path.getsize(p)\n    return sum(os.path.getsize(os.path.join(a, f)) for a, _, fs in os.walk(p) for f in fs if os.path.exists(os.path.join(a, f)))\n\n\ndef candidatos(root=ROOT):\n    out = []\n    for dirpath, dirs, files in os.walk(root):\n        rel_dir = os.path.relpath(dirpath, root)\n        top = rel_dir.split(os.sep)[0]\n        if top in PROTEGIDO and top != "src" and top != "tests":\n            dirs[:] = []\n            continue\n        for d in list(dirs):\n            if d in (".git", ".venv", "venv", "_poda", "checkpoints", "memory", "cartuchos"):\n                dirs.remove(d)\n            elif d in ("__pycache__", ".pytest_cache", ".parche_backups", ".mypy_cache", ".ruff_cache"):\n                out.append((os.path.join(dirpath, d), "cache o copia temporal"))\n                dirs.remove(d)\n        for f in files:\n            p = os.path.join(dirpath, f)\n            rel = os.path.relpath(p, root)\n            if f in (".DS_Store",) or f.endswith((".pyc", ".tmp")):\n                out.append((p, "temporal"))\n            elif os.path.dirname(rel) == "" and re.fullmatch(r"parche-\\d+\\.py", f):\n                out.append((p, "parche ya aplicado (git guarda su historia)"))\n            elif f.endswith(".zip") and os.path.dirname(rel) in ("", "reports"):\n                out.append((p, "paquete zip (se regenera con scripts.ciclo)"))\n            elif rel == os.path.join("data", "autoexamen.tsv"):\n                out.append((p, "generado (se regenera)"))\n    return sorted(out)\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    c = candidatos()\n    total = 0\n    for p, why in c:\n        s = _size(p)\n        total += s\n        print(f"  {s / 1024:9.1f} KB  {p}   [{why}]")\n    print(f"\\n{len(c)} elementos, {total / 1024 / 1024:.1f} MB.")\n    if "--aplicar" not in argv:\n        print("(simulacion: no se ha tocado nada. Para moverlos a _poda/:  python -m scripts.poda --aplicar)")\n        return 0\n    dest = os.path.join("_poda", time.strftime("%Y%m%d-%H%M%S"))\n    for p, _ in c:\n        t = os.path.join(dest, os.path.relpath(p, ROOT))\n        os.makedirs(os.path.dirname(t), exist_ok=True)\n        shutil.move(p, t)\n    print(f"Movidos a {dest}. Si todo va bien, puedes borrar _poda/ (y anadirlo a .gitignore).")\n    return 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'tests/test_parche91.py': '"""parche-91: preparacion de textos, cartuchos (insertar/retirar sin restos) y poda."""\nimport json\nimport os\n\nfrom src.language.ingesta import clasificar, comprobar, limpiar, preparar\nfrom src.memory import cartuchos\nfrom src.memory.store import MemoryStore\n\n\ndef test_preparar_texto():\n    txt = "# comentario\\nEl Sistema Solar\\nEl Sol es una estrella (la más cercana). Además, Marte es rojo; Venus es caliente.\\n"\n    frases, titulos = preparar(txt)\n    assert titulos == ["El Sistema Solar"]\n    assert frases == ["El Sol es una estrella.", "Marte es rojo.", "Venus es caliente."]\n\n\ndef test_limpiar_conectores_y_parentesis():\n    assert limpiar("Sin embargo, la Luna gira (despacio) alrededor de la Tierra.") == "La Luna gira alrededor de la Tierra."\n    assert limpiar("también tiene anillos.") == "Tiene anillos."\n\n\ndef test_clasificar():\n    assert clasificar("Entendido: MARTE SER ROJO.") == "aprendida"\n    assert clasificar("No he entendido «x». ¿Puedes decirlo con una frase más simple?") == "no_entendida"\n    assert clasificar("Vale.") == "otra"\n\n\nclass _Conv:\n    def say(self, q):\n        return "Marte es rojo y tiene dos lunas."\n\n\nclass _Mem:\n    display = {"MARTE": "Marte", "ROJO": "rojo", "LUNAS": "dos lunas"}\n\n\ndef test_comprobar_retencion():\n    hechos = [{"s": "MARTE", "p": "SER", "o": "ROJO"}, {"s": "MARTE", "p": "TENER", "o": "LUNAS"}, {"s": "MARTE", "p": "SER", "o": "AZUL"}]\n    ok, total, fallos = comprobar(_Conv(), _Mem(), hechos)\n    assert (ok, total) == (2, 3) and fallos[0][1] == "azul"\n\n\ndef _crear(tmp, nombre, hechos, disp):\n    mem = MemoryStore(str(tmp / "tmp.json"))\n    snap = cartuchos.instantanea(mem)\n    for s, p, o in hechos:\n        mem.add_fact((s, p, o), source="texto")\n    for k, v in disp.items():\n        mem.display[k] = v\n    mem.opposites.append(["frio", "caliente"])\n    cartuchos.guardar_cartucho(nombre, cartuchos.delta(mem, snap), {"fuente": "t.txt"}, base=str(tmp / "c"))\n    cartuchos.insertar(nombre, base=str(tmp / "c"))\n\n\ndef test_cartuchos_insertar_y_retirar_sin_restos(tmp_path):\n    base = str(tmp_path / "c")\n    _crear(tmp_path, "solar", [("MARTE", "SER", "ROJO")], {"MARTE": "Marte"})\n    _crear(tmp_path, "tabla", [("HIERRO", "SER", "METAL")], {"HIERRO": "el hierro"})\n    mem = MemoryStore(str(tmp_path / "personal.json"))\n    mem.add_fact(("ANA", "VIVIR_EN", "MADRID"))\n    mem.add_fact(("MARTE", "SER", "ROJO"))                       # el usuario ya lo habia dicho: su hecho manda\n    mem.display["ANA"] = "Ana"\n    assert dict(cartuchos.montar(mem, base=base)) == {"solar": 0, "tabla": 1}\n    assert mem.display["HIERRO"] == "el hierro" and ["frio", "caliente"] in mem.opposites\n    mem.save()                                                    # lo personal se guarda SIN lo de los cartuchos\n    data = json.load(open(mem.path, encoding="utf-8"))\n    assert [(f["s"], f["o"]) for f in data["facts"]] == [("ANA", "MADRID"), ("MARTE", "ROJO")] and "HIERRO" not in data["display"] and ["frio", "caliente"] not in data["opposites"]\n    cartuchos.retirar("tabla", base=base)                         # retirar uno: el otro y lo personal siguen\n    cartuchos.montar(mem, base=base)\n    assert not any(f["s"] == "HIERRO" for f in mem.facts) and "HIERRO" not in mem.display and ["frio", "caliente"] in mem.opposites\n    assert any(f["s"] == "ANA" for f in mem.facts) and mem.display["ANA"] == "Ana"\n    cartuchos.retirar("solar", base=base)\n    cartuchos.montar(mem, base=base)\n    assert ["frio", "caliente"] not in mem.opposites and {f["s"] for f in mem.facts} == {"ANA", "MARTE"}   # lo del usuario no se pierde\n    assert [x[:2] for x in cartuchos.listar(base)] == [("solar", False), ("tabla", False)]\n\n\ndef test_poda_simula_y_no_toca_protegidos(tmp_path, monkeypatch):\n    from scripts import poda\n    (tmp_path / "__pycache__").mkdir()\n    (tmp_path / "parche-12.py").write_text("x")\n    (tmp_path / "memory").mkdir()\n    (tmp_path / "memory" / "a.tmp").write_text("x")\n    (tmp_path / "src").mkdir()\n    (tmp_path / "src" / "a.py").write_text("x")\n    c = [os.path.relpath(p, str(tmp_path)) for p, _ in poda.candidatos(str(tmp_path))]\n    assert sorted(c) == ["__pycache__", "parche-12.py"]\n', 'data/textos/sistema_solar.txt': '# Ejemplo: sustituye este texto por el tuyo (lenguaje natural, frases completas).\nEl Sistema Solar\nEl Sol es una estrella. El Sol está en el centro del Sistema Solar. Los planetas giran alrededor del Sol.\nMercurio es el planeta más cercano al Sol. Venus es el segundo planeta. La Tierra es el tercer planeta y tiene una luna. La Luna gira alrededor de la Tierra.\nMarte es un planeta rojo. Marte tiene dos lunas. Júpiter es el planeta más grande. Júpiter es un gigante gaseoso. Saturno tiene anillos. Urano y Neptuno son planetas helados.\nPlutón es un planeta enano. Los asteroides son rocas pequeñas. Los cometas están hechos de hielo y polvo.\n'}

def main(root: Path = ROOT) -> int:
    stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f")
    bk = root / ".parche_backups" / stamp
    texts, changed = {}, set()
    for rel, old, new, marca in ALL_EDITS:                              # comprobar TODO antes de escribir nada
        p = root / rel
        if not p.is_file():
            print(f"FALTA {rel}: no se toca nada."); return 1
        txt = texts[rel] if rel in texts else p.read_text(encoding="utf-8")
        if marca in txt:
            texts[rel] = txt; continue
        if txt.count(old) != 1:
            print(f"ERROR {rel}: un trozo a cambiar aparece {txt.count(old)} veces (debe ser 1): {old[:70]!r}. No se toca nada."); return 1
        texts[rel] = txt.replace(old, new); changed.add(rel)
    plan = [(root / rel, rel, texts[rel]) for rel in sorted(changed)]
    for rel, content in NEW_FILES.items():
        p = root / rel
        if not p.exists() or p.read_text(encoding="utf-8") != content:
            plan.append((p, rel, content))
    for p, rel, txt in plan:
        if p.exists():
            (bk / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(p, bk / rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(txt, encoding="utf-8")
        if rel.endswith(".py"):
            py_compile.compile(str(p), doraise=True)
        print(f"  escrito {rel}")
    print(f"parche-91 instalado. Copias en {bk}" if plan else "parche-91: nada que hacer.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

